def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 anchor, found {count}")
    return text.replace(old, new, 1)


def find_matching_brace(text: str, open_index: int) -> int:
    if open_index < 0 or open_index >= len(text) or text[open_index] != "{":
        raise RuntimeError("invalid opening brace index")

    depth = 0
    index = open_index
    state = "code"

    while index < len(text):
        ch = text[index]
        nxt = text[index + 1] if index + 1 < len(text) else ""

        if state == "code":
            if ch == "/" and nxt == "/":
                state = "line_comment"
                index += 2
                continue
            if ch == "/" and nxt == "*":
                state = "block_comment"
                index += 2
                continue
            if ch == '"':
                state = "string"
                index += 1
                continue
            if ch == "'":
                state = "char"
                index += 1
                continue
            if ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    return index
            index += 1
            continue

        if state == "line_comment":
            if ch == "\n":
                state = "code"
            index += 1
            continue

        if state == "block_comment":
            if ch == "*" and nxt == "/":
                state = "code"
                index += 2
            else:
                index += 1
            continue

        if state in ("string", "char"):
            if ch == "\\":
                index += 2
                continue
            if (state == "string" and ch == '"') or (
                state == "char" and ch == "'"
            ):
                state = "code"
            index += 1
            continue

    raise RuntimeError("matching closing brace not found")


def find_function(text: str, signature: str) -> tuple[int, int]:
    """
    Find a function definition from its declaration prefix.

    The project formats some parameter lists across several lines, so the
    opening brace is not necessarily immediately after the supplied signature.
    """
    start = text.find(signature)

    if start < 0:
        raise RuntimeError(f"function prefix not found: {signature}")

    open_index = text.find("{", start + len(signature))
    semicolon_index = text.find(";", start + len(signature))

    if open_index < 0:
        raise RuntimeError(f"function opening brace not found: {signature}")

    if semicolon_index >= 0 and semicolon_index < open_index:
        raise RuntimeError(
            f"matched a declaration instead of a definition: {signature}"
        )

    close_index = find_matching_brace(text, open_index)
    return start, close_index + 1


def find_if_block_containing(
    text: str,
    condition_start: str,
    required_inside: str,
) -> tuple[int, int]:
    search_from = 0

    while True:
        start = text.find(condition_start, search_from)
        if start < 0:
            break

        open_index = text.find("{", start)
        if open_index < 0:
            break

        close_index = find_matching_brace(text, open_index)
        block = text[start:close_index + 1]

        if required_inside in block:
            return start, close_index + 1

        search_from = close_index + 1

    raise RuntimeError(
        f"matching if block not found: {condition_start} / {required_inside}"
    )


def main() -> int:
    root = Path.cwd().resolve()
    main_path = root / "src" / "main_3ds.c"

    if not main_path.is_file() or not (root / "Makefile.3ds").is_file():
        print("ERROR: run this from C:/Projects/AvP3DS/Source")
        print("Nothing changed.")
        return 1

    original = main_path.read_text(encoding="utf-8")

    if MARKER in original:
        print("ERROR: ALIEN-HUD1C3 is already installed.")
        print("Nothing changed.")
        return 1

    required_markers = (
        "ALIEN-HUD1A2-LOWER-HEALTH",
        "ALIEN-HUD1B2-LOWER-MESSAGES",
        "PRED-HUD1H-UPPER-SUPPRESS",
        "PRED-HUD1F3-SPEAR-AMMO-PINNED",
        "PRED-HUD1G-MESSAGE-RECENTER",
        "PRED-HUD1E3-SWAP-AND-DEATH-BLACK",
        "AVP-HUD1G1 tracker transform lock",
    )

    for marker in required_markers:
        if marker not in original:
            print(f"ERROR: required baseline marker missing: {marker}")
            print("Nothing changed.")
            return 1

    required_layouts = (
        "{ 84.0f, 36.0f, 144.0f, 88.0f, 1.35f }",
        "{ 10.0f, 124.0f, 86.0f, 78.0f, 1.00f }",
        "{ 208.0f, 124.0f, 112.0f, 78.0f, 0.82f }",
        "{ 40.0f, 0.0f, 240.0f, 32.0f, 0.86f }",
        "{ 116.0f, 72.0f, 88.0f, 32.0f, 1.25f }",
        "{ 64.0f, 184.0f, 192.0f, 44.0f, 1.00f }",
    )

    for entry in required_layouts:
        if original.count(entry) != 1:
            print(f"ERROR: completed layout missing or duplicated: {entry}")
            print("Nothing changed.")
            return 1

    shared_message_layout = "{ 40.0f, 16.0f, 240.0f, 32.0f, 0.86f }"
    if original.count(shared_message_layout) != 2:
        print(
            "ERROR: Predator/Alien shared message layout is not in "
            "the expected state."
        )
        print("Nothing changed.")
        return 1

    try:
        png_bytes = zlib.decompress(base64.b64decode(PNG_ZLIB_B64))
        rgba_bytes = zlib.decompress(base64.b64decode(RGBA_ZLIB_B64))
    except Exception as exc:
        print(f"ERROR: embedded backdrop decode failed: {exc}")
        print("Nothing changed.")
        return 1

    if len(rgba_bytes) != EXPECTED_RGBA_BYTES:
        print(
            f"ERROR: RGBA size is {len(rgba_bytes)}, "
            f"expected {EXPECTED_RGBA_BYTES}"
        )
        print("Nothing changed.")
        return 1

    if sha256(png_bytes) != EXPECTED_PNG_SHA256:
        print("ERROR: embedded PNG hash verification failed.")
        print("Nothing changed.")
        return 1

    if sha256(rgba_bytes) != EXPECTED_RGBA_SHA256:
        print("ERROR: embedded RGBA hash verification failed.")
        print("Nothing changed.")
        return 1

    text = original

    try:
        # ----------------------------------------------------------
        # Independent Alien texture globals.
        # ----------------------------------------------------------
        predator_globals = (
            "static C3D_Tex avp3ds_predator_hud_texture;\n"
            "static bool avp3ds_predator_hud_texture_initialized = false;\n"
        )

        alien_globals = predator_globals + f"""
/* {MARKER}: independent Alien lower-screen backdrop. */
static C3D_Tex avp3ds_alien_hud_texture;
static bool avp3ds_alien_hud_texture_initialized = false;
"""

        text = replace_once(
            text,
            predator_globals,
            alien_globals,
            "Alien texture globals",
        )

        # ----------------------------------------------------------
        # Clone the proven Predator loader into an Alien loader.
        # ----------------------------------------------------------
        pred_loader_start, pred_loader_end = find_function(
            text,
            "static bool AvP3DS_LoadPredatorHUDTexture(void)",
        )
        predator_loader = text[pred_loader_start:pred_loader_end]

        alien_loader = predator_loader
        alien_loader = alien_loader.replace(
            "static bool AvP3DS_LoadPredatorHUDTexture(void)",
            "static bool AvP3DS_LoadAlienHUDTexture(void)",
            1,
        )
        alien_loader = alien_loader.replace(
            "avp3ds_predator_hud_texture",
            "avp3ds_alien_hud_texture",
        )
        alien_loader = alien_loader.replace(
            "avp3ds_predator_hud_texture_initialized",
            "avp3ds_alien_hud_texture_initialized",
        )
        alien_loader = alien_loader.replace(
            "romfs:/Predator_HUD_Backdrop_320x240.rgba",
            "romfs:/Alien_HUD_Backdrop_320x240.rgba",
        )
        alien_loader = alien_loader.replace("Predator HUD", "Alien HUD")
        alien_loader = alien_loader.replace("Predator lower", "Alien lower")
        alien_loader = alien_loader.replace(
            "PRED-HUD1C3-NATIVE-BACKDROP",
            MARKER,
        )

        if "AvP3DS_LoadAlienHUDTexture" not in alien_loader:
            raise RuntimeError("Alien loader clone verification failed")

        text = (
            text[:pred_loader_end]
            + "\n\n"
            + alien_loader
            + text[pred_loader_end:]
        )

        # ----------------------------------------------------------
        # Clone the proven Predator load call.
        # ----------------------------------------------------------
        pred_load_start, pred_load_end = find_if_block_containing(
            text,
            "    if (!AvP3DS_LoadPredatorHUDTexture())",
            "Predator HUD native backdrop unavailable",
        )
        predator_load_block = text[pred_load_start:pred_load_end]

        alien_load_block = predator_load_block.replace(
            "AvP3DS_LoadPredatorHUDTexture",
            "AvP3DS_LoadAlienHUDTexture",
        ).replace(
            "Predator HUD",
            "Alien HUD",
        )

        text = (
            text[:pred_load_end]
            + "\n\n"
            + alien_load_block
            + text[pred_load_end:]
        )

        # ----------------------------------------------------------
        # Clone the proven Predator cleanup block.
        # ----------------------------------------------------------
        pred_cleanup_start, pred_cleanup_end = find_if_block_containing(
            text,
            "    if (avp3ds_predator_hud_texture_initialized)",
            "C3D_TexDelete(&avp3ds_predator_hud_texture);",
        )
        predator_cleanup = text[pred_cleanup_start:pred_cleanup_end]

        alien_cleanup = predator_cleanup.replace(
            "avp3ds_predator_hud_texture_initialized",
            "avp3ds_alien_hud_texture_initialized",
        ).replace(
            "avp3ds_predator_hud_texture",
            "avp3ds_alien_hud_texture",
        ).replace(
            "Predator texture cleanup is independent.",
            "Alien texture cleanup is independent.",
        ).replace(
            "PRED-HUD1C3-NATIVE-BACKDROP",
            MARKER,
        )

        text = (
            text[:pred_cleanup_end]
            + "\n\n"
            + alien_cleanup
            + text[pred_cleanup_end:]
        )

        # ----------------------------------------------------------
        # Clone the Predator backdrop quad, but use exact full-screen Y.
        # ----------------------------------------------------------
        pred_append_start, pred_append_end = find_function(
            text,
            "static void AvP3DS_AppendPredatorHUDBackdrop(",
        )
        predator_append = text[pred_append_start:pred_append_end]

        alien_append = predator_append.replace(
            "static void AvP3DS_AppendPredatorHUDBackdrop(",
            "static void AvP3DS_AppendAlienHUDBackdrop(",
            1,
        )
        alien_append = alien_append.replace(
            "PRED-HUD1D2-BACKDROP-DOWN8",
            MARKER,
        )
        alien_append = alien_append.replace(
            "Predator-only copy",
            "Alien-only copy",
        )
        alien_append = alien_append.replace(
            "Geometry is translated down by 12.0 lower-screen pixels.",
            "Geometry uses the exact 320x240 lower-screen bounds.",
        )
        alien_append = alien_append.replace(
            "const float topY = 12.0f;",
            "const float topY = 0.0f;",
        )
        alien_append = alien_append.replace(
            "AVP3DS_BOTTOM_HEIGHT + 12.0f;",
            "AVP3DS_BOTTOM_HEIGHT;",
        )

        if "AvP3DS_AppendAlienHUDBackdrop" not in alien_append:
            raise RuntimeError("Alien backdrop helper clone verification failed")

        text = (
            text[:pred_append_end]
            + "\n\n"
            + alien_append
            + text[pred_append_end:]
        )

        # ----------------------------------------------------------
        # Species-specific backdrop geometry routing.
        # ----------------------------------------------------------
        geometry_old = """    if (predatorHUDCaptured &&
        avp3ds_predator_hud_texture_initialized)
    {
        AvP3DS_AppendPredatorHUDBackdrop(
            gridVertices,
            &gridVertexCount);
    }
    else if (!predatorHUDCaptured &&
             !alienHUDCaptured &&
             avp3ds_marine_hud_texture_initialized)
"""

        geometry_new = """    if (alienHUDCaptured &&
        avp3ds_alien_hud_texture_initialized)
    {
        AvP3DS_AppendAlienHUDBackdrop(
            gridVertices,
            &gridVertexCount);
    }
    else if (predatorHUDCaptured &&
             avp3ds_predator_hud_texture_initialized)
    {
        AvP3DS_AppendPredatorHUDBackdrop(
            gridVertices,
            &gridVertexCount);
    }
    else if (!predatorHUDCaptured &&
             !alienHUDCaptured &&
             avp3ds_marine_hud_texture_initialized)
"""

        text = replace_once(
            text,
            geometry_old,
            geometry_new,
            "Alien backdrop geometry routing",
        )

        # ----------------------------------------------------------
        # Species-specific texture binding.
        # ----------------------------------------------------------
        bind_old = """    if (predatorHUDCaptured &&
        avp3ds_predator_hud_texture_initialized)
    {
        C3D_TexBind(
            0,
            &avp3ds_predator_hud_texture);
"""

        bind_new = """    if (alienHUDCaptured &&
        avp3ds_alien_hud_texture_initialized)
    {
        C3D_TexBind(
            0,
            &avp3ds_alien_hud_texture);

        C3D_TexEnvSrc(
            textureEnvironment,
            C3D_Both,
            GPU_TEXTURE0,
            GPU_PRIMARY_COLOR,
            0);

        C3D_TexEnvFunc(
            textureEnvironment,
            C3D_Both,
            GPU_MODULATE);
    }
    else if (predatorHUDCaptured &&
             avp3ds_predator_hud_texture_initialized)
    {
        C3D_TexBind(
            0,
            &avp3ds_predator_hud_texture);
"""

        text = replace_once(
            text,
            bind_old,
            bind_new,
            "Alien texture bind routing",
        )

        # ----------------------------------------------------------
        # Final safety checks.
        # ----------------------------------------------------------
        for entry in required_layouts:
            if text.count(entry) != 1:
                raise RuntimeError(f"completed layout changed: {entry}")

        if text.count(shared_message_layout) != 2:
            raise RuntimeError("shared Predator/Alien message layout changed")

        for marker in required_markers:
            if marker not in text:
                raise RuntimeError(f"completed milestone behavior lost: {marker}")

        required_tokens = (
            "static C3D_Tex avp3ds_alien_hud_texture;",
            "static bool AvP3DS_LoadAlienHUDTexture(void)",
            "romfs:/Alien_HUD_Backdrop_320x240.rgba",
            "static void AvP3DS_AppendAlienHUDBackdrop(",
            "AvP3DS_AppendAlienHUDBackdrop(",
            "&avp3ds_alien_hud_texture",
            "const float topY = 0.0f;",
            "ALIEN-HUD1B2-LOWER-MESSAGES",
        )

        for token in required_tokens:
            if token not in text:
                raise RuntimeError(f"Alien backdrop token missing: {token}")

        if text.count("romfs:/Marine_WY_HUD.rgba") != 1:
            raise RuntimeError("Marine backdrop path changed")

        if text.count("romfs:/Predator_HUD_Backdrop_320x240.rgba") != 1:
            raise RuntimeError("Predator backdrop path changed")

        if "const float topY = 12.0f;" not in text:
            raise RuntimeError("Predator +12 backdrop offset changed")

        death_clear = (
            "    C3D_RenderTargetClear(\n"
            "        avp3ds_bottom_target,\n"
            "        C3D_CLEAR_ALL,\n"
            "        0x000000FF,\n"
            "        0);\n"
        )

        if text.count(death_clear) != 1:
            raise RuntimeError("universal death-black clear changed")

        # The current Predator source carries only one replaceable native-
        # backdrop marker, while all functional Alien additions are verified
        # individually above. Require the installed milestone marker once.
        if text.count(MARKER) != 1:
            raise RuntimeError(
                "ALIEN-HUD1C3 marker verification failed: "
                f"expected 1, found {text.count(MARKER)}"
            )

    except Exception as exc:
        print(f"ERROR: {exc}")
        print("Nothing changed.")
        return 1

    assets_dir = root / "assets"
    romfs_dir = root / "romfs"
    png_out = assets_dir / "Alien_HUD_Backdrop_320x240.png"
    rgba_out = romfs_dir / "Alien_HUD_Backdrop_320x240.rgba"

    main_backup = main_path.with_name("main_3ds.c.pre-ALIEN-HUD1C3.bak")
    png_backup = png_out.with_name(
        "Alien_HUD_Backdrop_320x240.pre-ALIEN-HUD1C3.png.bak"
    )
    rgba_backup = rgba_out.with_name(
        "Alien_HUD_Backdrop_320x240.pre-ALIEN-HUD1C3.rgba.bak"
    )

    if main_backup.exists():
        print(f"ERROR: backup already exists: {main_backup}")
        print("Nothing changed.")
        return 1

    if png_out.exists() and png_backup.exists():
        print(f"ERROR: backup already exists: {png_backup}")
        print("Nothing changed.")
        return 1

    if rgba_out.exists() and rgba_backup.exists():
        print(f"ERROR: backup already exists: {rgba_backup}")
        print("Nothing changed.")
        return 1

    assets_dir.mkdir(parents=True, exist_ok=True)
    romfs_dir.mkdir(parents=True, exist_ok=True)

    shutil.copy2(main_path, main_backup)

    if png_out.exists():
        shutil.copy2(png_out, png_backup)

    if rgba_out.exists():
        shutil.copy2(rgba_out, rgba_backup)

    wrote_main = wrote_png = wrote_rgba = False

    try:
        main_path.write_text(text, encoding="utf-8")
        wrote_main = True

        png_out.write_bytes(png_bytes)
        wrote_png = True

        rgba_out.write_bytes(rgba_bytes)
        wrote_rgba = True

    except Exception as exc:
        if wrote_main:
            shutil.copy2(main_backup, main_path)

        if wrote_png:
            if png_backup.exists():
                shutil.copy2(png_backup, png_out)
            elif png_out.exists():
                png_out.unlink()

        if wrote_rgba:
            if rgba_backup.exists():
                shutil.copy2(rgba_backup, rgba_out)
            elif rgba_out.exists():
                rgba_out.unlink()

        print(f"ERROR while writing: {exc}")
        print("All modified files were restored.")
        return 1

    print("ALIEN-HUD1C3 installed successfully.")
    print(f"Backup: {main_backup}")
    if png_backup.exists():
        print(f"Backup: {png_backup}")
    if rgba_backup.exists():
        print(f"Backup: {rgba_backup}")
    print()
    print("Alien lower screen:")
    print("  - approved biomechanical/amber backdrop")
    print("  - messages remain in the upper amber panel")
    print("  - health remains in the lower amber panel")
    print("  - exact full-screen 320x240 placement")
    print()
    print("Marine, Predator, upper Alien effects, and death-black were preserved.")
    print(f"PNG SHA-256:  {sha256(png_bytes)}")
    print(f"RGBA SHA-256: {sha256(rgba_bytes)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
